pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint96 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(amount > 0 && amount <= type(uint96).max);
        c.init(address(this), address(this), address(this));
        uint256 beforeCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 afterCount = c.proposalCount();
        assertTrue(afterCount == beforeCount + 1);
    }
}
